const sample = {
  "demo": true,
  "prompt": "What happened to pricing this week?",
  "sessionId": "kpi"
};
const incoming = $input.first()?.json ?? {};
const provided = Object.keys(incoming).filter((key) => incoming[key] !== undefined && incoming[key] !== null && incoming[key] !== '');
const base = provided.length ? { ...sample, ...incoming } : { ...sample };
const flag = incoming.demo;
base.demo = !(flag === false || flag === 'false' || flag === 0 || flag === '0');
return [{ json: base }];

const item = $input.first().json;
const produced = (() => {

const book = {
  'pricing': 'Growth stayed at 149. No price test ran this week.'
};
const prompt = String(item.prompt || item.question || item.text || '').toLowerCase();
const keys = Object.keys(book);
const hit = keys.find((key) => prompt.includes(key)) || null;
const answer = hit ? book[hit] : 'I do not have a grounded answer for that in the demo knowledge set. Ask about: ' + keys.join(', ') + '.';
const record = { answer, topic: hit, persona: 'analyst', sessionId: item.sessionId || 'portfolio-demo' };
return {
  summary: answer,
  route: hit ? 'answered' : 'fallback',
  prompt: item.prompt || item.question || item.text || '',
  record,
  slackText: (hit ? 'Answered' : 'Fallback') + ': ' + answer,
  actions: [{ app: 'agent', operation: 'reply', payload: record }],
};

})();
if (!produced || typeof produced.summary !== 'string' || !produced.summary.trim()) {
  throw new Error('Apply rules must return a summary string');
}
return [{
  json: {
    ...item,
    ...produced,
    demo: item.demo !== false,
  },
}];

const item = $input.first().json;
return [{
  json: {
    demo: true,
    status: 'demo_ready',
    workflow: 'sheets-analyst-agent',
    summary: item.summary,
    route: item.route ?? null,
    record: item.record ?? {},
    actions: item.actions ?? [],
    slackText: item.slackText ?? item.summary,
    notes: 'Demo mode did not call external apps. Send {"demo": false} after placeholder credentials are replaced.',
  },
}];
